from taf.config.testline import EPCSim, LTEEmuCore, PrismaCore


class CoreAttrs(object):

    def __init__(self, core):
        self.core = core

    def get_mme_ip(self):
        self._check_if_core()
        return self.core.mme_ip

    def get_mnc(self):
        self._check_if_core()
        return self.core.mnc

    def get_mcc(self):
        self._check_if_core()
        return self.core.mcc

    def has_epcsim(self):
        return isinstance(self.core, EPCSim)

    def has_lteemu_core(self):
        return isinstance(self.core, LTEEmuCore)

    def has_prisma_core(self):
        return isinstance(self.core, PrismaCore)

    def _check_if_core(self):
        if self.core is None:
            raise AttributeError('Core attribute was not found in testline.')
